 Outcome<PoliticalResponsibilityExecution> political_responsibility_for_execution(const StableId&,const PoliticalResponsibilityRef& ref,const WorldIdentity& identity)const override{auto out=find_political_responsibility_for_execution(ref,identity);if(!out.ok||!out.value)return {false,{},common_failure("MissingTestTakeover").error};return {true,*out.value,{}};}
 Outcome<std::optional<PoliticalResponsibilityExecution>> political_responsibility_before_fact(const PoliticalResponsibilityRef& ref,const StableId& id,Integer,const WorldIdentity& identity)const override{bool registered=false,decided=false;for(const auto& row:common.state().facts.rows()){if(row.first==current.registration_fact_id)registered=true;if(current.decision&&row.first==current.decision->decision_fact_id)decided=true;if(row.first==id){if(!registered)return {true,std::nullopt,{}};auto out=find_political_responsibility_for_execution(ref,identity);if(out.ok&&out.value&&!decided){out.value->status=PoliticalResponsibilityExecutionStatus::pending;out.value->decision.reset();out.value->code="PoliticalResponsibilityPending";}return out;}}return {false,{},common_failure("UnknownTestReliefFact").error};}
